-- Гид: пляжи, климат, сезонные риски, доступная среда. Ориентиры, а не гарантия — погода и природа меняются.




-- Доступная среда: базовые правила по классу отеля, затем точечные уточнения
UPDATE hotel SET elevator = stars >= 4, accessible_room = stars = 5 OR (stars = 4 AND get_byte(decode(md5(name), 'hex'), 0) < 128), step_free_access = stars = 5 OR (stars = 4 AND get_byte(decode(md5(name), 'hex'), 0) < 160);
UPDATE hotel SET terrain = 'STEEP' WHERE city IN ('Ялта', 'Севастополь');
UPDATE hotel SET terrain = 'HILLY' WHERE city IN ('Кемер', 'Стамбул', 'Сочи', 'Красная Поляна', 'Гагра', 'Тбилиси', 'Алушта', 'Судак', 'Кисловодск', 'Дербент', 'Владивосток', 'Нижний Новгород', 'Ереван', 'Дилижан', 'Шеки', 'Чемал', 'Листвянка', 'Куинстаун', 'Светлогорск');
UPDATE hotel SET accessible_room = FALSE, step_free_access = FALSE WHERE name IN ('Coral Atoll Island Resort', 'Gion Machiya Stay', 'Asakusa Ryokan Garden', 'Higashiyama Onsen Ryokan', 'Ичан-Кала Инн', 'Шеки Караван-Сарай', 'Хостел Дворцовый', 'Ливадия Хиллс', 'Фиолент Скалы', 'Kamala Luxury Villas', 'Ubud Rice Terrace Villas');
UPDATE hotel SET accessible_room = TRUE, step_free_access = TRUE, elevator = TRUE WHERE name IN ('Palm Cove Reef Retreat', 'Circular Quay Harbour Hotel', 'Имеретинский Берег', 'Jumeirah Sands Resort', 'Marina Bay Vista');
