INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('59ef2bd8-cb5c-5f7b-99a0-7eb3ec47aded', 'Пляж Белека', 'Турция', 'Белек', ST_SetSRID(ST_MakePoint(31.061, 36.8545), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 16000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['банан и таблетка', 'парасейлинг', 'гидроциклы', 'пляжный волейбол'], TRUE, TRUE, TRUE, 'У большинства отелей — дорожки до воды и шезлонги у кромки', 'Длинный песчаный пляж с пологим входом и чистым морем, отели — в сосновой зоне.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('df17ebea-a308-5ccb-99f2-8ad43efb836f', 'Пляж Соргун — Колаклы', 'Турция', 'Сиде', ST_SetSRID(ST_MakePoint(31.401, 36.771), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 20000, 'MEDIUM', ARRAY['WINDSURFING'], ARRAY['WINDSURFING:5,6,7,8,9'], ARRAY['банан', 'парасейлинг', 'прокат SUP', 'катамараны'], TRUE, TRUE, TRUE, 'Пляжи отелей ровные, есть настилы к воде', 'Мягкий песок, мелководье у берега. После обеда часто поднимается ветер и небольшая волна.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('55e8b69a-2534-5417-bd2a-098f825eed38', 'Пляж Гёйнюк — Бельдиби', 'Турция', 'Кемер', ST_SetSRID(ST_MakePoint(30.5615, 36.606), 4326)::geography, 'COARSE_PEBBLE', FALSE, 'STEEP', TRUE, 'Глубина начинается через 2–3 шага, у берега сразу с головой', 'NONE', NULL, 9000, 'MEDIUM', ARRAY['DIVING', 'SNORKELING'], '{}'::text[], ARRAY['катамараны', 'гидроциклы', 'дайв-центры', 'морские прогулки на яхте'], FALSE, FALSE, FALSE, 'Крупная галька до самой воды — коляске и тем, кто неуверенно ходит, сложно', 'Самая прозрачная вода побережья, горы Тавр за спиной. Нужны коралловые тапочки: галька крупная.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('dcd6630a-be4a-5db6-9ad4-b5e7f6ac20b2', 'Пляж Лара', 'Турция', 'Анталья', ST_SetSRID(ST_MakePoint(30.836, 36.853), 4326)::geography, 'DARK_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 12000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['банан', 'парасейлинг', 'гидроциклы', 'аквапарки рядом'], TRUE, TRUE, TRUE, 'Ровный широкий пляж, у новых отелей — пандусы и настилы', 'Тёмный крупный песок, нагревается сильнее светлого — в июле горячо босиком. Очень пологий вход.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('93305341-950f-52be-977b-67f4f23b9e33', 'Пляж Махмутлар', 'Турция', 'Аланья', ST_SetSRID(ST_MakePoint(31.994, 36.5445), 4326)::geography, 'MIXED', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 4000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['банан', 'катера'], TRUE, TRUE, FALSE, 'Пляж городской, к воде — через дорогу и по песку с галькой', 'Песок с мелкой галькой, вход постепенный. Вдоль пляжа — городская набережная.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('2f5dd959-5797-5777-8170-89ed2477b40b', 'Центральный пляж Сочи', 'Россия', 'Сочи', ST_SetSRID(ST_MakePoint(39.7175, 43.579), 4326)::geography, 'COARSE_PEBBLE', FALSE, 'STEEP', TRUE, 'Через 3–5 м от кромки глубина больше роста', 'NONE', NULL, 2000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['банан и таблетка', 'катера', 'кафе на пляже'], FALSE, FALSE, FALSE, 'Набережная с пандусами, но до воды — крупная галька', 'Городской галечный пляж у Морского вокзала. Народу много, к вечеру тише.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('72eaf51b-2491-5ed7-920d-4400a18862b2', 'Пляж «Ривьера»', 'Россия', 'Сочи', ST_SetSRID(ST_MakePoint(39.7145, 43.5935), 4326)::geography, 'COARSE_PEBBLE', FALSE, 'STEEP', TRUE, 'Глубина нарастает быстро', 'NONE', NULL, 1200, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['водные велосипеды', 'кафе', 'шезлонги'], FALSE, FALSE, FALSE, 'Ступени и галька', 'Благоустроенный галечный пляж у парка «Ривьера».');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('d192e170-0495-592e-b27e-1d9d3c7399cb', 'Имеретинский пляж', 'Россия', 'Сочи', ST_SetSRID(ST_MakePoint(39.95, 43.403), 4326)::geography, 'FINE_PEBBLE', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 6000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['прокат велосипедов', 'SUP', 'пляжные кафе'], TRUE, TRUE, TRUE, 'Олимпийская набережная: пандусы, спуски к воде, широкие дорожки', 'Мелкая галька с песком, широкий пляж и самая удобная набережная Сочи для колясок и велосипедов.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('858c1c09-fc3b-5844-bfe0-d54cc0eb33f8', 'Пляж Адлера', 'Россия', 'Сочи', ST_SetSRID(ST_MakePoint(39.919, 43.4285), 4326)::geography, 'MIXED', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 3000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['банан', 'катера', 'аквапарк «Амфибиус» рядом'], TRUE, TRUE, FALSE, 'Песок с галькой, к воде без настилов', 'Галька с песком, вход ровнее, чем в центре Сочи.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('e04602c9-3760-5b70-ab31-3f280389f566', 'Пляж Хосты', 'Россия', 'Сочи', ST_SetSRID(ST_MakePoint(39.8655, 43.5145), 4326)::geography, 'COARSE_PEBBLE', FALSE, 'STEEP', TRUE, 'Глубоко почти сразу', 'NONE', NULL, 1500, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['кафе'], FALSE, FALSE, FALSE, 'Крутой спуск и галька', 'Небольшой галечный пляж под горой, тише центра.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('3259f84b-79ae-52b0-b484-d349c40a7792', 'Пляж Гагры', 'Абхазия', 'Гагра', ST_SetSRID(ST_MakePoint(40.2485, 43.2805), 4326)::geography, 'FINE_PEBBLE', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 4000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['катера', 'кафе'], TRUE, TRUE, FALSE, 'Галька и спуски без пандусов', 'Мелкая галька, очень чистая и прозрачная вода — горные реки рядом холодят море.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('829049e0-8380-58af-9601-8771ecdf89d9', 'Пляж Батуми', 'Грузия', 'Батуми', ST_SetSRID(ST_MakePoint(41.6245, 41.6485), 4326)::geography, 'COARSE_PEBBLE', FALSE, 'STEEP', TRUE, 'Галечный откос: глубина начинается почти от кромки', 'NONE', NULL, 7000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['катамараны', 'парасейлинг', 'бары'], FALSE, FALSE, FALSE, 'Бульвар доступный, но спуск к воде — по крупной гальке', 'Длинный галечный пляж вдоль Приморского бульвара. Коралловые тапочки обязательны.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('957204e3-0194-5da7-98d1-f7bfa51e4406', 'Пляж Патонг', 'Таиланд', 'Пхукет', ST_SetSRID(ST_MakePoint(98.2955, 7.8955), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', 'Отлив заметный, но купаться можно весь день', 3000, 'HIGH', ARRAY['SURFING'], ARRAY['SURFING:5,6,7,8,9,10'], ARRAY['парасейлинг', 'гидроциклы', 'банан', 'бары на Бангла-роуд'], TRUE, TRUE, FALSE, 'Широкая набережная, к воде — по песку', 'Самый шумный и тусовочный пляж Пхукета. С мая по октябрь — волны и красные флаги.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('4daa017e-e028-506d-a0d6-5911f689a4f7', 'Пляж Ката', 'Таиланд', 'Пхукет', ST_SetSRID(ST_MakePoint(98.2975, 7.8195), 4326)::geography, 'WHITE_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', NULL, 1500, 'MEDIUM', ARRAY['SURFING', 'SNORKELING'], ARRAY['SURFING:5,6,7,8,9,10', 'SNORKELING:11,12,1,2,3,4'], ARRAY['серф-школы', 'SUP', 'каяки'], TRUE, TRUE, FALSE, 'Песок до воды, пандусов нет', 'Белый песок и коралловые камни на южном краю для снорклинга. В сухой сезон — спокойное море для детей.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('74ce45e0-2b89-5fd1-84e1-08eb1fa39a73', 'Пляж Карон', 'Таиланд', 'Пхукет', ST_SetSRID(ST_MakePoint(98.2935, 7.8465), 4326)::geography, 'WHITE_SAND', FALSE, 'MODERATE', TRUE, 'Резкий уклон: через несколько метров глубина по грудь, в сезон дождей сильный прибой', 'MODERATE', NULL, 4000, 'LOW', ARRAY['SURFING'], ARRAY['SURFING:6,7,8,9'], ARRAY['гидроциклы', 'бары'], FALSE, TRUE, FALSE, 'Широкий песок без настилов', 'Длинный пляж со «скрипучим» кварцевым песком и простором даже в сезон.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('6d76caca-e904-5f64-9cee-12e0f18411b5', 'Пляж Камала', 'Таиланд', 'Пхукет', ST_SetSRID(ST_MakePoint(98.282, 7.9545), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', 'В отлив вода отходит на 20–30 м', 2000, 'LOW', '{}'::text[], '{}'::text[], ARRAY['SUP', 'массаж на пляже'], TRUE, TRUE, FALSE, 'Песок, без пандусов', 'Тихий пляж для семей, отели на склоне — виды, но и подъёмы.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('54ab5ece-ddd8-5bda-a679-576b3d38038a', 'Пляж Джомтьен', 'Таиланд', 'Паттайя', ST_SetSRID(ST_MakePoint(100.8735, 12.8905), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', NULL, 6000, 'MEDIUM', ARRAY['KITESURFING', 'WINDSURFING'], ARRAY['KITESURFING:11,12,1,2', 'WINDSURFING:11,12,1,2'], ARRAY['гидроциклы', 'банан', 'кайт-станции'], TRUE, TRUE, TRUE, 'Набережная с пандусами после реконструкции', 'Спокойнее центральной Паттайи. Вода у берега мутноватая — за прозрачной ездят на остров Ко Лан.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('0af604f3-0dc4-5ef3-afef-b537a8da7ee4', 'Пляж Чавенг', 'Таиланд', 'Самуи', ST_SetSRID(ST_MakePoint(100.0635, 9.53), 4326)::geography, 'WHITE_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', 'В северной части летом сильный отлив — до рифа по колено', 6000, 'HIGH', ARRAY['SNORKELING'], '{}'::text[], ARRAY['гидроциклы', 'огненные шоу', 'бары'], TRUE, TRUE, FALSE, 'Песок до воды', 'Главный пляж Самуи: мелкий белый песок, бары и рестораны. В ноябре—декабре — волны и дожди.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('26ec934f-df73-58b3-991c-381c0ebee18a', 'Пляж Ламай', 'Таиланд', 'Самуи', ST_SetSRID(ST_MakePoint(100.0585, 9.4725), 4326)::geography, 'GOLDEN_SAND', FALSE, 'MODERATE', FALSE, NULL, 'MODERATE', NULL, 4000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['массаж', 'бары'], TRUE, TRUE, FALSE, 'Песок, без настилов', 'Крупный золотистый песок, на юге — скалы Хин Та и Хин Яй.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('b1ca34fb-b62a-54ee-ae06-c9526df6df11', 'Пляж Ао Нанг', 'Таиланд', 'Краби', ST_SetSRID(ST_MakePoint(98.8215, 8.0315), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'STRONG', 'В отлив вода отходит на 50–100 м: мелководье и камни. Купаться удобнее в прилив — смотрите таблицу приливов', 1500, 'HIGH', ARRAY['SNORKELING'], ARRAY['SNORKELING:11,12,1,2,3,4'], ARRAY['лодки на острова Пхи-Пхи', 'каякинг в мангровых', 'скалолазание'], TRUE, TRUE, FALSE, 'Набережная ровная, к воде — песок', 'Известняковые скалы и лодки-лонгтейлы на острова.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('7b5dfed7-9d6a-52eb-9925-8dcf30c5c21d', 'Пляж Чан Фу', 'Вьетнам', 'Нячанг', ST_SetSRID(ST_MakePoint(109.1975, 12.2445), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', NULL, 6000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['парасейлинг', 'банан', 'бары', 'канатная дорога на остров'], TRUE, TRUE, TRUE, 'Городская набережная с пандусами', 'Городской пляж вдоль набережной. С октября по декабрь — волны и штормы.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('6cd09293-f045-58dd-b539-90f00a039929', 'Пляж Бай Зай (Камрань)', 'Вьетнам', 'Нячанг', ST_SetSRID(ST_MakePoint(109.215, 12.011), 4326)::geography, 'WHITE_SAND', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 15000, 'LOW', ARRAY['SURFING'], ARRAY['SURFING:10,11,12'], ARRAY['пляжные клубы'], TRUE, TRUE, FALSE, 'Песок, ограниченная инфраструктура', 'Длинный пустынный пляж у аэропорта Камрань. В сезон ветров — сильная волна и течения.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('fa5ca861-c34b-5754-b1b0-f784cdbc1fae', 'Лонг-Бич (Фукуок)', 'Вьетнам', 'Фукуок', ST_SetSRID(ST_MakePoint(103.9575, 10.216), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'MODERATE', NULL, 20000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['бары на закате', 'ночной рынок'], TRUE, TRUE, FALSE, 'Песок, без настилов', 'Закатный пляж западного берега. С июня по сентябрь — волны и мусор после штормов.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('096dca8e-0168-552f-a248-2b307b5318a4', 'Пляж Бай Сао', 'Вьетнам', 'Фукуок', ST_SetSRID(ST_MakePoint(104.0365, 10.0575), 4326)::geography, 'WHITE_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 3000, 'LOW', ARRAY['SNORKELING'], ARRAY['SNORKELING:11,12,1,2,3,4'], ARRAY['лодки на острова Ан Тхой', 'каяки'], TRUE, TRUE, FALSE, 'Песок, мало инфраструктуры', 'Самый белый песок острова, бирюзовая вода и мелководье на десятки метров.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('12969e74-bc72-5031-a244-0e72eb7a3b85', 'Пляж Ми Кхе', 'Вьетнам', 'Дананг', ST_SetSRID(ST_MakePoint(108.2485, 16.0605), 4326)::geography, 'WHITE_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 9000, 'MEDIUM', ARRAY['SURFING'], ARRAY['SURFING:9,10,11,12,1,2'], ARRAY['серф-школы', 'SUP', 'кафе'], TRUE, TRUE, TRUE, 'Ровная набережная с пандусами и спусками', 'Широкий городской пляж с мелким песком. Осенью и зимой — волны для серфинга.');
