INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('f850e7aa-106c-5bb1-a5f5-39716d0ed516', 'Яшмовый пляж (Фиолент)', 'Россия', 'Севастополь', ST_SetSRID(ST_MakePoint(33.4885, 44.502), 4326)::geography, 'FINE_PEBBLE', FALSE, 'STEEP', TRUE, 'Глубина сразу 2–3 м, дно каменистое', 'NONE', NULL, 300, 'MEDIUM', ARRAY['SNORKELING', 'DIVING'], '{}'::text[], '{}'::text[], FALSE, FALSE, FALSE, 'Спуск — около 800 ступеней', 'Один из красивейших пляжей Крыма: прозрачная вода, скалы, но тяжёлый спуск.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('b8fb4fcd-02fa-52e1-b62b-6f4a0336b33a', 'Пляж Судака', 'Россия', 'Судак', ST_SetSRID(ST_MakePoint(34.9785, 44.8425), 4326)::geography, 'MIXED', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 2000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['банан', 'катера в Новый Свет'], TRUE, TRUE, TRUE, 'Набережная с пандусами', 'Песок с мелкой галькой, пологий вход.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('76b2fb38-239f-5546-aa85-7e8ea3534596', 'Пляж Джемете', 'Россия', 'Анапа', ST_SetSRID(ST_MakePoint(37.2795, 44.9295), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 10000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['банан', 'аквапарки', 'батуты'], TRUE, TRUE, TRUE, 'Деревянные настилы к воде', 'Песчаные дюны и мелководье на 50–100 м — классика отдыха с маленькими детьми.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('f91b332e-d7c6-5302-b87c-4fec47ba8079', 'Центральный пляж Анапы', 'Россия', 'Анапа', ST_SetSRID(ST_MakePoint(37.312, 44.896), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 1500, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['банан', 'кафе'], TRUE, TRUE, TRUE, 'Набережная и пандусы', 'Песчаный пляж у центра города.');
