INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('a7832f77-cc39-52bd-bb54-4f7f2e072a48', 'Пляж Светлогорска', 'Россия', 'Светлогорск', ST_SetSRID(ST_MakePoint(20.1515, 54.9465), 4326)::geography, 'GOLDEN_SAND', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 1500, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['променад', 'кафе'], FALSE, TRUE, TRUE, 'К морю — на городском лифте, по променаду ровно', 'Узкий пляж под высоким обрывом. Балтика прохладная и часто с волной.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('3aa33e4d-8a12-5809-b6d2-3de145b791ca', 'Пляж Зеленоградска', 'Россия', 'Зеленоградск', ST_SetSRID(ST_MakePoint(20.4795, 54.9615), 4326)::geography, 'WHITE_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 3000, 'MEDIUM', ARRAY['KITESURFING', 'SURFING'], ARRAY['KITESURFING:5,6,7,8,9', 'SURFING:9,10,11'], ARRAY['кайт-станции', 'серф-школы'], TRUE, TRUE, TRUE, 'Деревянные настилы и пандусы', 'Широкий светлый пляж, ветреный — любимое место кайтеров Балтики.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('eec9fbcb-424e-5921-a5b2-29a895ea82de', 'Городской пляж Актау', 'Казахстан', 'Актау', ST_SetSRID(ST_MakePoint(51.1545, 43.6455), 4326)::geography, 'SHELL_SAND', FALSE, 'MODERATE', FALSE, NULL, 'NONE', NULL, 1000, 'MEDIUM', '{}'::text[], '{}'::text[], ARRAY['кафе'], TRUE, TRUE, FALSE, 'Берег местами скалистый, бетонные спуски', 'Каспий: песок с ракушкой и скалистый берег. Часто ветрено.');
INSERT INTO beach (id, name, country, city, location, surface, artificial_sand, entry, depth_drop, depth_note, tides, tide_note, length_m, crowd, activities, activity_seasons, entertainment, kids_friendly, seniors_friendly, accessible, accessibility_note, description) VALUES ('ad029fcc-afb9-5137-93b9-102525de683e', 'Пляж Чолпон-Аты', 'Кыргызстан', 'Чолпон-Ата', ST_SetSRID(ST_MakePoint(77.0795, 42.6465), 4326)::geography, 'GOLDEN_SAND', FALSE, 'GENTLE', FALSE, NULL, 'NONE', NULL, 2000, 'HIGH', '{}'::text[], '{}'::text[], ARRAY['катера', 'банан'], TRUE, TRUE, FALSE, 'Песок', 'Крупный песок, чистейшая вода горного озера — бодрящая даже в августе.');
